def count_bowl_subarrays(nums):
    stack=[];answer=0
    for right,value in enumerate(nums):
        while stack and nums[stack[-1]]<value:
            left=stack.pop()
            if right-left>=2:answer+=1
        if stack and right-stack[-1]>=2:answer+=1
        stack.append(right)
    return answer

